	logger := slog.New(slog.NewTextHandler(os.Stdout, nil))

	s := scheduler.New(
		scheduler.WithMiddleware(
			scheduler.Recovery(func(jobName string, r interface{}) {
				logger.Error("Job panicked", "job", jobName, "panic", r)
			}),
